package hsm

import (
	"errors"
	"fmt"

	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/crypto"
	"github.com/miekg/pkcs11"
)

// InitResult is what the one-off init prints: public data only.
type InitResult struct {
	Address   common.Address
	PublicKey []byte
	NewToken  bool
	// AttestPublicKey is the 65-byte uncompressed P-256 public key of the attestation key generated by this run
	// (the value to pin outside the database, key-custody-hsm.md invariant 10). nil when none was generated.
	AttestPublicKey []byte
	// KEKVersion is the version of the vault KEK (kek-v1) generated by this run (key-custody-hsm.md M3c); 0 when none was generated.
	KEKVersion int
}

// InitTokenAndKey is the one-off `init-token` subcommand: it initialises the token labelled
// cfg.TokenLabel when it does not exist (SO PIN typed by the operator, never stored; the user PIN is
// read from cfg.PINFile), then generates the Hot Key INSIDE the token: secp256k1,
// CKA_PRIVATE=true, CKA_SENSITIVE=true, CKA_EXTRACTABLE=false. It refuses to run when a Hot Key
// with that label already exists, and never re-initialises an existing token (C_InitToken on an
// initialised token erases it).
func InitTokenAndKey(cfg Config, soPIN string) (*InitResult, error) {
	userPIN, err := ReadPIN(cfg.PINFile)
	if err != nil {
		return nil, err
	}
	ctx := pkcs11.New(cfg.Module)
	if ctx == nil {
		return nil, fmt.Errorf("cannot load %s", cfg.Module)
	}
	defer ctx.Destroy()
	if err := ctx.Initialize(); err != nil {
		return nil, Map("Initialize", err)
	}
	defer func() { _ = ctx.Finalize() }()

	res := &InitResult{}
	slot, err := findSlot(ctx, cfg.TokenLabel)
	var he *Error
	switch {
	case err == nil: // token exists: reuse it, do not re-initialise
	case errors.As(err, &he) && he.Code == CodeTokenMissing:
		if soPIN == "" {
			return nil, errors.New("token does not exist and no SO PIN was given")
		}
		free, ferr := uninitialisedSlot(ctx)
		if ferr != nil {
			return nil, ferr
		}
		if err := ctx.InitToken(free, soPIN, cfg.TokenLabel); err != nil {
			return nil, Map("InitToken", err)
		}
		// SoftHSM renumbers slots after InitToken: look the token up again by label.
		if slot, err = findSlot(ctx, cfg.TokenLabel); err != nil {
			return nil, err
		}
		s, err := ctx.OpenSession(slot, pkcs11.CKF_SERIAL_SESSION|pkcs11.CKF_RW_SESSION)
		if err != nil {
			return nil, Map("OpenSession", err)
		}
		if err := ctx.Login(s, pkcs11.CKU_SO, soPIN); err != nil {
			_ = ctx.CloseSession(s)
			return nil, Map("Login SO", err)
		}
		if err := ctx.InitPIN(s, userPIN); err != nil {
			_ = ctx.CloseSession(s)
			return nil, Map("InitPIN", err)
		}
		_ = ctx.Logout(s)
		_ = ctx.CloseSession(s)
		res.NewToken = true
	default:
		return nil, err
	}

	s, err := ctx.OpenSession(slot, pkcs11.CKF_SERIAL_SESSION|pkcs11.CKF_RW_SESSION)
	if err != nil {
		return nil, Map("OpenSession", err)
	}
	defer func() { _ = ctx.CloseSession(s) }()
	if err := ctx.Login(s, pkcs11.CKU_USER, userPIN); err != nil {
		return nil, Map("Login", err)
	}
	defer func() { _ = ctx.Logout(s) }()

	for _, class := range []uint{pkcs11.CKO_PRIVATE_KEY, pkcs11.CKO_PUBLIC_KEY} {
		if err := ctx.FindObjectsInit(s, []*pkcs11.Attribute{
			pkcs11.NewAttribute(pkcs11.CKA_CLASS, class), pkcs11.NewAttribute(pkcs11.CKA_LABEL, cfg.KeyLabel)}); err != nil {
			return nil, Map("FindObjectsInit", err)
		}
		objs, _, err := ctx.FindObjects(s, 1)
		_ = ctx.FindObjectsFinal(s)
		if err != nil {
			return nil, Map("FindObjects", err)
		}
		if len(objs) > 0 {
			return nil, fmt.Errorf("a key labelled %q already exists in the token: refusing to create a second Hot Key", cfg.KeyLabel)
		}
	}

	pubT := []*pkcs11.Attribute{
		pkcs11.NewAttribute(pkcs11.CKA_CLASS, pkcs11.CKO_PUBLIC_KEY),
		pkcs11.NewAttribute(pkcs11.CKA_KEY_TYPE, pkcs11.CKK_EC),
		pkcs11.NewAttribute(pkcs11.CKA_EC_PARAMS, secp256k1OID),
		pkcs11.NewAttribute(pkcs11.CKA_TOKEN, true),
		pkcs11.NewAttribute(pkcs11.CKA_VERIFY, true),
		pkcs11.NewAttribute(pkcs11.CKA_LABEL, cfg.KeyLabel),
	}
	privT := []*pkcs11.Attribute{
		pkcs11.NewAttribute(pkcs11.CKA_CLASS, pkcs11.CKO_PRIVATE_KEY),
		pkcs11.NewAttribute(pkcs11.CKA_KEY_TYPE, pkcs11.CKK_EC),
		pkcs11.NewAttribute(pkcs11.CKA_TOKEN, true),
		pkcs11.NewAttribute(pkcs11.CKA_PRIVATE, true), // explicit: M0 (d), private=false is plaintext at rest
		pkcs11.NewAttribute(pkcs11.CKA_SENSITIVE, true),
		pkcs11.NewAttribute(pkcs11.CKA_EXTRACTABLE, false),
		pkcs11.NewAttribute(pkcs11.CKA_SIGN, true),
		pkcs11.NewAttribute(pkcs11.CKA_LABEL, cfg.KeyLabel),
	}
	pubH, _, err := ctx.GenerateKeyPair(s, []*pkcs11.Mechanism{pkcs11.NewMechanism(pkcs11.CKM_EC_KEY_PAIR_GEN, nil)}, pubT, privT)
	if err != nil {
		return nil, Map("GenerateKeyPair", err)
	}
	attrs, err := ctx.GetAttributeValue(s, pubH, []*pkcs11.Attribute{pkcs11.NewAttribute(pkcs11.CKA_EC_POINT, nil)})
	if err != nil {
		return nil, Map("read public key", err)
	}
	raw, err := ParseECPoint(attrs[0].Value)
	if err != nil {
		return nil, err
	}
	pk, err := crypto.UnmarshalPubkey(raw)
	if err != nil {
		return nil, err
	}
	res.PublicKey, res.Address = raw, crypto.PubkeyToAddress(*pk)
	if res.AttestPublicKey, err = genAttestKey(ctx, s, cfg.attestLabel()); err != nil {
		return nil, err
	}
	if err := genKEK(ctx, s, 1); err != nil {
		return nil, err
	}
	res.KEKVersion = 1
	return res, nil
}

// InitKEK is the one-off `init-kek` subcommand for a token that was initialised before M3c (it has a Hot Key and an
// attestation key and no vault KEK): it generates kek-v1 INSIDE the token, AES-256, CKA_PRIVATE=true, CKA_SENSITIVE=true,
// CKA_EXTRACTABLE=false, wrap/unwrap only, a different object from the Hot Key and the attestation key. It refuses when any
// KEK already exists (later versions are made by key-admin rotate-kek through the gateway, inside a Maintenance Window).
func InitKEK(cfg Config) (int, error) {
	userPIN, err := ReadPIN(cfg.PINFile)
	if err != nil {
		return 0, err
	}
	ctx := pkcs11.New(cfg.Module)
	if ctx == nil {
		return 0, fmt.Errorf("cannot load %s", cfg.Module)
	}
	defer ctx.Destroy()
	if err := ctx.Initialize(); err != nil {
		return 0, Map("Initialize", err)
	}
	defer func() { _ = ctx.Finalize() }()
	slot, err := findSlot(ctx, cfg.TokenLabel)
	if err != nil {
		return 0, err
	}
	s, err := ctx.OpenSession(slot, pkcs11.CKF_SERIAL_SESSION|pkcs11.CKF_RW_SESSION)
	if err != nil {
		return 0, Map("OpenSession", err)
	}
	defer func() { _ = ctx.CloseSession(s) }()
	if err := ctx.Login(s, pkcs11.CKU_USER, userPIN); err != nil {
		return 0, Map("Login", err)
	}
	defer func() { _ = ctx.Logout(s) }()
	if err := genKEK(ctx, s, 1); err != nil {
		return 0, err
	}
	return 1, nil
}

// genKEK generates kek-v{version} inside the token, refusing when any object of the KEK label family version already exists
// (a second kek-v1 would make "which key wrapped this" ambiguous).
func genKEK(ctx *pkcs11.Ctx, s pkcs11.SessionHandle, version int) error {
	for v := 1; v <= MaxKEKVersion; v++ {
		if err := ctx.FindObjectsInit(s, []*pkcs11.Attribute{
			pkcs11.NewAttribute(pkcs11.CKA_CLASS, pkcs11.CKO_SECRET_KEY), pkcs11.NewAttribute(pkcs11.CKA_LABEL, kekLabel(v))}); err != nil {
			return Map("FindObjectsInit", err)
		}
		objs, _, err := ctx.FindObjects(s, 1)
		_ = ctx.FindObjectsFinal(s)
		if err != nil {
			return Map("FindObjects", err)
		}
		if len(objs) > 0 {
			return fmt.Errorf("a KEK labelled %q already exists in the token: refusing to create another with init-kek (use key-admin rotate-kek)", kekLabel(v))
		}
	}
	if _, err := ctx.GenerateKey(s, []*pkcs11.Mechanism{pkcs11.NewMechanism(pkcs11.CKM_AES_KEY_GEN, nil)}, kekTemplate(version)); err != nil {
		return Map("GenerateKey (KEK)", err)
	}
	return nil
}

// InitAttestKey is the one-off `init-attest-key` subcommand for a token that was initialised before M3a (it has a
// Hot Key and no attestation key): it generates the attestation key INSIDE the token, a P-256 key with
// CKA_PRIVATE=true, CKA_SENSITIVE=true, CKA_EXTRACTABLE=false, and returns its public key. It refuses when a key with
// that label exists (a second attestation key would make "which key is pinned" ambiguous) and when the label is the
// Hot Key's.
func InitAttestKey(cfg Config) ([]byte, error) {
	if cfg.attestLabel() == cfg.KeyLabel {
		return nil, errors.New("the attestation key label equals the Hot Key label")
	}
	userPIN, err := ReadPIN(cfg.PINFile)
	if err != nil {
		return nil, err
	}
	ctx := pkcs11.New(cfg.Module)
	if ctx == nil {
		return nil, fmt.Errorf("cannot load %s", cfg.Module)
	}
	defer ctx.Destroy()
	if err := ctx.Initialize(); err != nil {
		return nil, Map("Initialize", err)
	}
	defer func() { _ = ctx.Finalize() }()
	slot, err := findSlot(ctx, cfg.TokenLabel)
	if err != nil {
		return nil, err
	}
	s, err := ctx.OpenSession(slot, pkcs11.CKF_SERIAL_SESSION|pkcs11.CKF_RW_SESSION)
	if err != nil {
		return nil, Map("OpenSession", err)
	}
	defer func() { _ = ctx.CloseSession(s) }()
	if err := ctx.Login(s, pkcs11.CKU_USER, userPIN); err != nil {
		return nil, Map("Login", err)
	}
	defer func() { _ = ctx.Logout(s) }()
	return genAttestKey(ctx, s, cfg.attestLabel())
}

// genAttestKey generates the P-256 attestation key pair inside the token (refusing a duplicate label).
func genAttestKey(ctx *pkcs11.Ctx, s pkcs11.SessionHandle, label string) ([]byte, error) {
	for _, class := range []uint{pkcs11.CKO_PRIVATE_KEY, pkcs11.CKO_PUBLIC_KEY} {
		if err := ctx.FindObjectsInit(s, []*pkcs11.Attribute{
			pkcs11.NewAttribute(pkcs11.CKA_CLASS, class), pkcs11.NewAttribute(pkcs11.CKA_LABEL, label)}); err != nil {
			return nil, Map("FindObjectsInit", err)
		}
		objs, _, err := ctx.FindObjects(s, 1)
		_ = ctx.FindObjectsFinal(s)
		if err != nil {
			return nil, Map("FindObjects", err)
		}
		if len(objs) > 0 {
			return nil, fmt.Errorf("a key labelled %q already exists in the token: refusing to create a second attestation key", label)
		}
	}
	pubT := []*pkcs11.Attribute{
		pkcs11.NewAttribute(pkcs11.CKA_CLASS, pkcs11.CKO_PUBLIC_KEY),
		pkcs11.NewAttribute(pkcs11.CKA_KEY_TYPE, pkcs11.CKK_EC),
		pkcs11.NewAttribute(pkcs11.CKA_EC_PARAMS, p256OID),
		pkcs11.NewAttribute(pkcs11.CKA_TOKEN, true),
		pkcs11.NewAttribute(pkcs11.CKA_VERIFY, true),
		pkcs11.NewAttribute(pkcs11.CKA_LABEL, label),
	}
	privT := []*pkcs11.Attribute{
		pkcs11.NewAttribute(pkcs11.CKA_CLASS, pkcs11.CKO_PRIVATE_KEY),
		pkcs11.NewAttribute(pkcs11.CKA_KEY_TYPE, pkcs11.CKK_EC),
		pkcs11.NewAttribute(pkcs11.CKA_TOKEN, true),
		pkcs11.NewAttribute(pkcs11.CKA_PRIVATE, true), // explicit: M0 (d), private=false is plaintext at rest
		pkcs11.NewAttribute(pkcs11.CKA_SENSITIVE, true),
		pkcs11.NewAttribute(pkcs11.CKA_EXTRACTABLE, false),
		pkcs11.NewAttribute(pkcs11.CKA_SIGN, true),
		pkcs11.NewAttribute(pkcs11.CKA_LABEL, label),
	}
	pubH, _, err := ctx.GenerateKeyPair(s, []*pkcs11.Mechanism{pkcs11.NewMechanism(pkcs11.CKM_EC_KEY_PAIR_GEN, nil)}, pubT, privT)
	if err != nil {
		return nil, Map("GenerateKeyPair (attestation key)", err)
	}
	attrs, err := ctx.GetAttributeValue(s, pubH, []*pkcs11.Attribute{pkcs11.NewAttribute(pkcs11.CKA_EC_POINT, nil)})
	if err != nil {
		return nil, Map("read attestation public key", err)
	}
	return ParseECPoint(attrs[0].Value)
}

func uninitialisedSlot(ctx *pkcs11.Ctx) (uint, error) {
	slots, err := ctx.GetSlotList(true)
	if err != nil {
		return 0, Map("GetSlotList", err)
	}
	for _, s := range slots {
		ti, err := ctx.GetTokenInfo(s)
		if err == nil && ti.Flags&pkcs11.CKF_TOKEN_INITIALIZED == 0 {
			return s, nil
		}
	}
	return 0, errors.New("no free slot to initialise a token in (is the token directory writable?)")
}
